// ─────────────────────────────────────────────────────────
//  MORPHIC PLAYGROUND — WEB WORKER SHELL (v0.6 W4).
//
//  One generic shell, instantiated twice by the page (a
//  check worker and a synthesis worker, so a long synthesis
//  never queues a check behind it). Each instance loads the
//  SAME pkg/ module the corpus runner exercises and the
//  fallback path calls directly (../pkg/morphic_wasm.js,
//  generated by playground/build.sh — never hand-edited).
//
//  Protocol (documented in playground/README.md):
//    page → worker   { id, kind: 'check', source }
//                    { id, kind: 'synthesize', source, specName, seed }
//    worker → page   { kind: 'ready' }            (once, after init)
//                    { id, ok: true,  report }    (report = the pkg
//                    { id, ok: false, error }      function's JSON string)
//  Requests are processed one at a time, in arrival order.
//  Cancellation is not a message: the page terminates the
//  worker and spawns a fresh instance (see main.js).
// ─────────────────────────────────────────────────────────
import init, { check, synthesize_seeded_spec } from '../pkg/morphic_wasm.js';

await init();

self.onmessage = (event) => {
  const { id, kind, source, specName, seed } = event.data ?? {};
  try {
    let report;
    if (kind === 'check') {
      report = check(source);
    } else if (kind === 'synthesize') {
      report = synthesize_seeded_spec(source, specName, seed);
    } else {
      throw new Error(`unknown request kind: ${String(kind)}`);
    }
    self.postMessage({ id, ok: true, report });
  } catch (err) {
    self.postMessage({ id, ok: false, error: String(err) });
  }
};

self.postMessage({ kind: 'ready' });
